module prio_encoder8_fix(
    input  [7:0] req,
    output reg [2:0] code,
    output       valid
);
    assign valid = |req;

    // The highest numbered request must win.
    always @(*) begin
        if (req[0])      code = 3'd0;
        else if (req[1]) code = 3'd1;
        else if (req[2]) code = 3'd2;
        else if (req[3]) code = 3'd3;
        else if (req[4]) code = 3'd4;
        else if (req[5]) code = 3'd5;
        else if (req[6]) code = 3'd6;
        else if (req[7]) code = 3'd7;
        else             code = 3'd0;
    end
endmodule

