module gray_to_bin_fix(
    input  [3:0] g,
    output [3:0] b
);
    // Standard Gray decode: each binary bit folds in every Gray bit
    // from its own position up to the most significant.
    assign b[3] = g[3];
    assign b[2] = g[3] ^ g[2];
    assign b[1] = g[3] ^ g[2] ^ g[1];
    assign b[0] = g[2] ^ g[1] ^ g[0];
endmodule

