module seq_det_101_overlap_fix(
    input       clk,
    input       rst_n,
    input       din,
    output      hit
);
    localparam S0   = 2'b00;  // no progress
    localparam S1   = 2'b01;  // seen 1
    localparam S10  = 2'b10;  // seen 10
    localparam S101 = 2'b11;  // accept

    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S0;
        end else begin
            case (state)
                S0:      state <= din ? S1   : S0;
                S1:      state <= din ? S1   : S10;
                S10:     state <= din ? S101 : S0;
                default: state <= din ? S0   : S10;
            endcase
        end
    end

    assign hit = (state == S101);
endmodule

